+function Get-AutomationHealth {
+    $results = New-Object System.Collections.Generic.List[object]
+
+    # --- Morning cadence: parse sentinel lines out of the mixed log ---
+    $cadenceLog = Join-Path $Root "outputs\morning\cadence.log"
