+    if (Test-Path -LiteralPath $cadenceLog) {
+        foreach ($line in (Get-Content -LiteralPath $cadenceLog -Tail 1000)) {
+            if ($line -match '^\[(?<ts>[^\]]+)\] cadence OK\s*$') {
+                $ts = Get-CadenceTimestamp $Matches.ts
+                if ($ts) { $lastOk = $ts }
+            } elseif ($line -match '^\[(?<ts>[^\]]+)\] cadence FAILED:?(?<why>.*)$') {
+                $ts = Get-CadenceTimestamp $Matches.ts
+                if ($ts) { $lastFail = $ts; $lastFailText = $Matches.why.Trim() }
+            }
+        }
+    }
+    $cadenceAge = if ($lastOk) { [math]::Round(((Get-Date) - $lastOk).TotalDays, 1) } else { $null }
+    $cadenceStatus = "OK"
+    $cadenceDetail = "last OK $cadenceAge day(s) ago"
+    if (-not $lastOk) {
+        $cadenceStatus = "NEVER-RAN"; $cadenceDetail = "no 'cadence OK' line in $cadenceLog"
+    } elseif ($lastFail -and $lastFail -gt $lastOk) {
+        $cadenceStatus = "FAILING"; $cadenceDetail = "last run failed: $lastFailText"
+    } elseif ($cadenceAge -gt 3.5) {
+        $cadenceStatus = "STALE"; $cadenceDetail = "last OK $cadenceAge days ago (threshold 3.5 - weekday task)"
+    }
+    $results.Add([pscustomobject]@{ Name = "Morning cadence"; Status = $cadenceStatus; LastSuccess = $lastOk; AgeDays = $cadenceAge; Detail = $cadenceDetail })
+
+    # --- Agy sync: freshness of outputs\agy ---
+    $agyDir = Join-Path $Root "outputs\agy"
+    $agyStatus = "NEVER-RAN"; $agyDetail = "no files under outputs\agy"; $agyLast = $null; $agyAge = $null
+    if (Test-Path -LiteralPath $agyDir) {
+        $newest = Get-ChildItem -LiteralPath $agyDir -Recurse -File -ErrorAction SilentlyContinue |
+            Where-Object { $_.Name -ne ".gitkeep" } |
+            Sort-Object LastWriteTime -Descending | Select-Object -First 1
+        if ($newest) {
+            $agyLast = $newest.LastWriteTime
+            $agyAge = [math]::Round(((Get-Date) - $agyLast).TotalDays, 1)
+            if ($agyAge -le 1.0) { $agyStatus = "OK"; $agyDetail = "newest output $($newest.Name), $agyAge day(s) old" }
+            else { $agyStatus = "STALE"; $agyDetail = "newest output $agyAge days old (task runs every 6h)" }
+        }
+    }
+    $results.Add([pscustomobject]@{ Name = "Agy sync"; Status = $agyStatus; LastSuccess = $agyLast; AgeDays = $agyAge; Detail = $agyDetail })
