@@ -0,0 +1,72 @@
+$ErrorActionPreference = "Stop"
+function Assert-True($Condition, $Message) { if (-not $Condition) { throw $Message } }
+
+$repoRoot = Resolve-Path (Join-Path $PSScriptRoot "..")
+$sourceScript = Join-Path $repoRoot "scripts\keystone.ps1"
+$tempRoot = Join-Path ([System.IO.Path]::GetTempPath()) ("keystone-autohealth-test-" + [System.Guid]::NewGuid().ToString("n"))
+
+try {
+    New-Item -ItemType Directory -Force -Path (Join-Path $tempRoot "scripts") | Out-Null
+    New-Item -ItemType Directory -Force -Path (Join-Path $tempRoot "data") | Out-Null
+    New-Item -ItemType Directory -Force -Path (Join-Path $tempRoot "outputs\morning") | Out-Null
+    Copy-Item -LiteralPath $sourceScript -Destination (Join-Path $tempRoot "scripts\keystone.ps1")
+    Set-Content -Path (Join-Path $tempRoot "data\projects.json") -Encoding UTF8 -Value '{ "projects": [] }'
+    $script = Join-Path $tempRoot "scripts\keystone.ps1"
+    $log = Join-Path $tempRoot "outputs\morning\cadence.log"
+
+    # Case 1: no log at all -> NEVER-RAN, and health must not crash
+    $out = & $script health *>&1 | Out-String
+    Assert-True ($out -match "Automation") "health must print an Automation section."
+    Assert-True ($out -match "NEVER-RAN") "Missing cadence.log must report NEVER-RAN."
+
+    # Case 2: fresh OK line (with interleaved junk output around it) -> OK
+    $fresh = (Get-Date).AddHours(-2).ToString("o")
+    Set-Content -Path $log -Encoding UTF8 -Value @(
+        "Dashboard: C:\somewhere\index.html",
+        "[$fresh] cadence OK",
+        "trailing junk line from *>> redirect"
+    )
+    $out = & $script health *>&1 | Out-String
+    Assert-True ($out -match "Morning cadence\s+OK") "Fresh OK line must report OK."
+
+    # Case 3: OK older than 3.5 days -> STALE
+    $old = (Get-Date).AddDays(-5).ToString("o")
+    Set-Content -Path $log -Encoding UTF8 -Value "[$old] cadence OK"
+    $out = & $script health *>&1 | Out-String
+    Assert-True ($out -match "STALE") "5-day-old OK must report STALE."
+
+    # Case 4: FAILED after the last OK -> FAILING
+    $okTs = (Get-Date).AddDays(-1).ToString("o")
+    $failTs = (Get-Date).AddHours(-1).ToString("o")
+    Set-Content -Path $log -Encoding UTF8 -Value @(
+        "[$okTs] cadence OK",
+        "[$failTs] cadence FAILED: The term 'okr.py' is not recognized"
+    )
+    $out = & $script health *>&1 | Out-String
+    Assert-True ($out -match "FAILING") "FAILED newer than OK must report FAILING."
+
+    # Case 5: agy outputs stale (>24h) -> STALE row for AgySync
+    $agyDir = Join-Path $tempRoot "outputs\agy"
+    New-Item -ItemType Directory -Force -Path $agyDir | Out-Null
+    $marker = Join-Path $agyDir "sync-summary.md"
+    Set-Content -Path $marker -Encoding UTF8 -Value "x"
+    (Get-Item $marker).LastWriteTime = (Get-Date).AddDays(-3)
+    $out = & $script health *>&1 | Out-String
+    Assert-True ($out -match "Agy sync\s+STALE") "3-day-old agy output must report STALE."
+
+    # Case 6: cockpit renders a warning banner when automation is unhealthy
+    & $script cockpit *>$null
+    $html = Get-Content -Raw -Path (Join-Path $tempRoot "outputs\dashboard\cockpit.html")
+    Assert-True ($html -match "Automation warning") "Cockpit must render an automation warning banner when a check is not OK."
+    Assert-True ($html -match "Agy sync") "Banner must name the failing automation."
+
+    # Case 7: healthy state -> no banner
+    Set-Content -Path $log -Encoding UTF8 -Value "[$((Get-Date).AddHours(-2).ToString('o'))] cadence OK"
+    (Get-Item $marker).LastWriteTime = Get-Date
+    & $script cockpit *>$null
+    $html = Get-Content -Raw -Path (Join-Path $tempRoot "outputs\dashboard\cockpit.html")
+    Assert-True (-not ($html -match "Automation warning")) "Healthy automations must not render the banner."
+
+    Write-Host "keystone automation-health tests passed"
+}
+finally { if (Test-Path $tempRoot) { Remove-Item -LiteralPath $tempRoot -Recurse -Force } }

